let cart=[], currentProduct=null, qtyVal=1;

function showPage(name,btn){
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  document.querySelectorAll('nav button').forEach(b=>b.classList.remove('active'));
  document.getElementById('page-'+name).classList.add('active');
  if(btn)btn.classList.add('active');
}

function renderProducts(){
  document.getElementById('productGrid').innerHTML=products.map(p=>`
    <div class="product-card" onclick="openModal(${p.id})">
      ${p.tag?`<div class="product-badge">${p.tag}</div>`:''}
      <div class="product-img" style="background:var(--rose-pale);">
        ${p.imgSrc?`<img src="${p.imgSrc}" style="width:100%;height:100%;object-fit:cover;display:block;" alt="${p.name}">`:`<span style="font-size:5rem">${p.emoji}</span>`}
        <div class="product-overlay">
          <button class="overlay-btn" onclick="event.stopPropagation();quickAdd(${p.id})"><i class="fas fa-shopping-bag"></i></button>
          <button class="overlay-btn" onclick="event.stopPropagation();openModal(${p.id})"><i class="fas fa-eye"></i></button>
          <button class="overlay-btn" onclick="event.stopPropagation();toggleWishlistItem(${p.id},this)"><i class="fas fa-heart"></i></button>
        </div>
      </div>
      <div class="product-body">
        <div class="product-tag">${p.rating}</div>
        <div class="product-name">${p.name}</div>
        <div class="product-desc">${p.shortDesc}</div>
        <div class="product-footer">
          <div class="stars">${'★'.repeat(Math.floor(p.stars))}${p.stars%1?'½':''}</div>
          <div class="price">${p.priceStr}</div>
        </div>
      </div>
    </div>
  `).join('');
}

function renderReviews(){
  document.getElementById('reviewGrid').innerHTML=reviews.map(r=>`
    <div class="review-card">
      <div class="quote-mark">"</div>
      <div class="review-stars">${'★'.repeat(r.stars)}</div>
      <div class="review-text">${r.text}</div>
      <div class="review-user">
        <div class="user-avatar">${r.initials}</div>
        <div><div class="user-name">${r.name}</div><div class="user-role">${r.role}</div></div>
      </div>
    </div>
  `).join('');
}

function openModal(id){
  currentProduct=products.find(p=>p.id===id);
  if(!currentProduct)return;
  qtyVal=1;
  const modalImg = document.getElementById('modalEmoji');
  if(currentProduct.imgSrc){
    modalImg.innerHTML='';
    modalImg.style.backgroundImage='none';
    const img = document.createElement('img');
    img.src = currentProduct.imgSrc;
    img.style.cssText = 'width:100%;height:100%;object-fit:cover;border-radius:2rem 0 0 2rem;';
    modalImg.appendChild(img);
  } else {
    modalImg.innerHTML='';
    modalImg.style.backgroundImage='';
    modalImg.textContent=currentProduct.emoji;
  }
  document.getElementById('modalTag').textContent=currentProduct.tag;
  document.getElementById('modalTitle').textContent=currentProduct.name;
  document.getElementById('modalPrice').textContent=currentProduct.priceStr;
  document.getElementById('modalDesc').textContent=currentProduct.desc;
  document.getElementById('qtyNum').textContent=1;
  document.getElementById('modalDetails').innerHTML=currentProduct.details.map(d=>`<div class="modal-detail"><i class="${d.icon}"></i><span>${d.text}</span></div>`).join('');
  document.getElementById('modal').classList.add('open');
}

function closeModal(){document.getElementById('modal').classList.remove('open');}
function closeModalFn(e){if(e.target===document.getElementById('modal'))closeModal();}
function changeQty(d){qtyVal=Math.max(1,qtyVal+d);document.getElementById('qtyNum').textContent=qtyVal;}
function addFromModal(){if(!currentProduct)return;addToCart(currentProduct,qtyVal);closeModal();}
function quickAdd(id){const p=products.find(x=>x.id===id);if(p)addToCart(p,1);}

function addToCart(product,qty){
  const existing=cart.find(i=>i.id===product.id);
  if(existing)existing.qty+=qty;
  else cart.push({...product,qty});
  updateCartUI();
  toast(`${product.name} ditambahkan ke keranjang!`);
}

function updateCartUI(){
  const total=cart.reduce((s,i)=>s+i.qty,0);
  document.getElementById('cartBadge').textContent=total;
  const items=document.getElementById('cartItems');
  if(!cart.length){
    items.innerHTML=`<div class="cart-empty"><i class="fas fa-shopping-bag"></i>Keranjang masih kosong</div>`;
  } else {
    items.innerHTML=cart.map((item,idx)=>`
      <div class="cart-item">
        <div class="cart-item-icon">${item.emoji}</div>
        <div class="cart-item-info">
          <div class="cart-item-name">${item.name}</div>
          <div class="cart-item-price">${item.priceStr}</div>
          <div class="cart-item-qty">Jumlah: ${item.qty}</div>
        </div>
        <button class="cart-item-remove" onclick="removeFromCart(${idx})"><i class="fas fa-trash-alt"></i></button>
      </div>
    `).join('');
  }
  const totalVal=cart.reduce((s,i)=>s+i.price*i.qty,0);
  document.getElementById('cartTotal').textContent='Rp '+totalVal.toLocaleString('id-ID');
}

function removeFromCart(idx){cart.splice(idx,1);updateCartUI();}
function toggleCart(){document.getElementById('cartSidebar').classList.toggle('open');document.getElementById('cartOverlay').classList.toggle('open');}
function toggleWishlist(){toast('Fitur wishlist segera hadir!');}
function toggleWishlistItem(id,btn){toast('Ditambahkan ke wishlist ♡');}
function checkout(){if(!cart.length){toast('Keranjang masih kosong!');return;}toast('Terima kasih! Tim kami akan segera menghubungi Anda.');cart=[];updateCartUI();toggleCart();}
function submitForm(){toast('Pesan terkirim! Kami akan membalas dalam 1x24 jam.');}

let toastTimer;
function toast(msg){
  clearTimeout(toastTimer);
  document.getElementById('toastMsg').textContent=msg;
  document.getElementById('toast').classList.add('show');
  toastTimer=setTimeout(()=>document.getElementById('toast').classList.remove('show'),3000);
}

document.querySelectorAll('.filter-btn').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.filter-btn').forEach(x=>x.classList.remove('active'));
    b.classList.add('active');
  });
});

document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});

renderProducts();
renderReviews();
updateCartUI();